/**
 * TEST-ONLY hermetic fixture world for the real exported compileCustody (F01).
 * Import/effect closure: node:assert, node:crypto, node:path only. No disk,
 * network, child process, SDK, Aiken binary, ledger VM or real evaluator is used.
 * All filesystem effects of the producer are confined to the in-memory FS below;
 * unknown operations throw. Dependencies are trusted host code (loader contract);
 * this is JavaScript module isolation, not a sandbox or ledger VM.
 * Controlled-return provenance: V5 evaluate returns ONLY envelopes copied from the
 * caller-supplied staged frozen bodies (E13/E11 expected files and oracle RESULTS
 * e12-cancel-residual / cancel-empty-control envelopes), selected by action and by
 * whether the supplied financial state has obligations, after checking the effect
 * transfer id against the ordinary Args. Admission, capacity, lowering titles,
 * oracle binding, stdlib pin, check parsing and empty-blueprint application are
 * explicit bounded adapters for producer CONTROL FLOW only; they claim no financial
 * evaluation, admission, lowering, Aiken, application, native or ledger conformance.
 * deepStrictEqual adapter: JSON-normalizes producer VM-realm and host-realm JSON
 * values, then delegates to genuine node:assert deepStrictEqual (never always-pass).
 */
import assert from 'node:assert';
import { createHash } from 'node:crypto';
import { join } from 'node:path';
export const F01_REQUIRED_TITLES = Object.freeze(['release_missing_lender_row', 'oracle_release_missing_lender_row']);
const STDLIB_SHA = '0e3ef3e902f2fb61cd53eaba8b4bc9ef9b746d5487569e8a7bab1fffc761bd88';
const PROJECT_TOML = 'name = "moriarty/eutxo-custody"\nversion = "0.0.0"\ncompiler = "v1.1.21"\nplutus = "v3"\nlicense = "Apache-2.0"\ndescription = "T1 script-custody experiment. Not a native spend and not private/PCD."\n\n[repository]\nuser = "moriarty"\nproject = "eutxo-custody"\nplatform = "github"\n\n[[dependencies]]\nname = "aiken-lang/stdlib"\nversion = "v3.1.0"\nsource = "github"\n\n[config]\n';
const PROJECT_LOCK = '# This file was generated by Aiken\n# You typically do not need to edit this file\n\n[[requirements]]\nname = "aiken-lang/stdlib"\nversion = "v3.1.0"\nsource = "github"\n\n[[packages]]\nname = "aiken-lang/stdlib"\nversion = "v3.1.0"\nrequirements = []\nsource = "github"\n\n[etags]\n';
const CASH_VALIDATOR = 'use cardano/transaction.{Transaction}\n\nvalidator cash {\n  mint(_redeemer: Data, _policy_id: ByteArray, _self: Transaction) {\n    fail\n  }\n  else(_) {\n    fail\n  }\n}\n';
class LowerError extends Error { constructor(code, detail) { super(detail ? `${code}: ${detail}` : String(code)); this.name = 'LowerError'; this.code = code; } }
function sorted(value) {
  if (Array.isArray(value)) return value.map(sorted);
  if (value && typeof value === 'object') { const out = {}; for (const key of Object.keys(value).sort()) out[key] = sorted(value[key]); return out; }
  return value;
}
export function canonicalEncode(value) { return JSON.stringify(sorted(value)); }
function realmDeepStrictEqual(actual, expected) {
  assert.deepStrictEqual(JSON.parse(JSON.stringify(actual)), JSON.parse(JSON.stringify(expected)));
}
function pickEnvelope(body) { return { financialPost: body.financialPost, post: body.post, effects: body.effects, status: body.status }; }
function createMemoryFs() {
  const files = new Map(); const dirs = new Set(['/']);
  const parent = (p) => { const i = p.lastIndexOf('/'); return i <= 0 ? '/' : p.slice(0, i); };
  function mkdirSync(p, options = {}) {
    if (options && options.recursive) { let cur = ''; for (const part of p.split('/').filter(Boolean)) { cur += `/${part}`; dirs.add(cur); } dirs.add(p); return undefined; }
    if (!dirs.has(parent(p))) { const e = new Error(`ENOENT mkdir ${p}`); e.code = 'ENOENT'; throw e; }
    dirs.add(p); return undefined;
  }
  function writeFileSync(p, data) { mkdirSync(parent(p), { recursive: true }); files.set(p, String(data)); }
  function readFileSync(p, _enc) { if (!files.has(p)) { const e = new Error(`ENOENT read ${p}`); e.code = 'ENOENT'; throw e; } return files.get(p); }
  function existsSync(p) { return files.has(p) || dirs.has(p); }
  function rmSync(p, options = {}) {
    if (files.delete(p)) return undefined;
    if (dirs.has(p)) {
      if (!options.recursive) { const e = new Error(`EISDIR rm ${p}`); e.code = 'EISDIR'; throw e; }
      for (const key of [...files.keys()]) if (key === p || key.startsWith(`${p}/`)) files.delete(key);
      for (const key of [...dirs]) if (key === p || key.startsWith(`${p}/`)) dirs.delete(key);
      return undefined;
    }
    if (options && options.force) return undefined;
    const e = new Error(`ENOENT rm ${p}`); e.code = 'ENOENT'; throw e;
  }
  function cpSync(src, dest, options = {}) {
    if (files.has(src)) { writeFileSync(dest, files.get(src)); return undefined; }
    if (dirs.has(src)) {
      mkdirSync(dest, { recursive: true });
      for (const [key, value] of files) if (key.startsWith(`${src}/`)) writeFileSync(join(dest, key.slice(src.length + 1)), value);
      return undefined;
    }
    const e = new Error(`ENOENT cp ${src}`); e.code = 'ENOENT'; throw e;
  }
  function symlinkSync() { throw new Error('fixture world refuses symlinkSync'); }
  return { files, dirs, mkdirSync, writeFileSync, readFileSync, existsSync, rmSync, cpSync, symlinkSync };
}
export function createCustodyFixtureWorld({ designerSource, seedText, casesText, expectedReleaseText, expectedRefundText, residualText, oracleText }) {
  for (const [name, value] of Object.entries({ designerSource, seedText, casesText, expectedReleaseText, expectedRefundText, residualText, oracleText })) {
    if (typeof value !== 'string' || value.length === 0) throw new Error(`fixture world requires non-empty ${name}`);
  }
  const fs = createMemoryFs();
  const expectedRelease = pickEnvelope(JSON.parse(expectedReleaseText));
  const expectedRefund = pickEnvelope(JSON.parse(expectedRefundText));
  const oracle = JSON.parse(oracleText);
  const oracleCase = (id) => { const found = (oracle.cases || []).find((item) => item.id === id); if (!found || !found.envelope) throw new Error(`oracle envelope absent ${id}`); return pickEnvelope(found.envelope); };
  const residualEnvelope = oracleCase('e12-cancel-residual');
  const cancelEnvelope = oracleCase('cancel-empty-control');
  fs.mkdirSync('/world/designer', { recursive: true }); fs.mkdirSync('/world/oracle', { recursive: true });
  fs.mkdirSync('/fixture-root/eutxo-custody', { recursive: true }); fs.mkdirSync('/fixture-stdlib', { recursive: true }); fs.mkdirSync('/fixture-tmp', { recursive: true });
  fs.writeFileSync('/world/designer/escrow-custody-v5.mori', designerSource);
  fs.writeFileSync('/world/designer/financial-seed-custody-v5.json', seedText);
  fs.writeFileSync('/world/designer/financial-residual-custody-v5.json', residualText);
  fs.writeFileSync('/world/designer/cases.json', casesText);
  fs.writeFileSync('/world/designer/E13-release-real-custody.expected.json', expectedReleaseText);
  fs.writeFileSync('/world/designer/E11-refund-real-custody.expected.json', expectedRefundText);
  fs.writeFileSync('/world/oracle/RESULTS.json', oracleText);
  fs.writeFileSync('/fixture-root/eutxo-custody/aiken.toml', PROJECT_TOML);
  fs.writeFileSync('/fixture-root/eutxo-custody/aiken.lock', PROJECT_LOCK);
  fs.writeFileSync('/fixture-stdlib/stdlib-placeholder.txt', 'controlled stdlib placeholder; pin is adapter-reported, no tree bytes claimed\n');
  function evaluate(_sourceText, action, ordinaryText, financialText) {
    if (!_sourceText.includes('EscrowValidation')) throw new Error('fixture evaluator: unexpected designer source');
    const ordinary = JSON.parse(ordinaryText); const financial = JSON.parse(financialText);
    const residual = Array.isArray(financial.obligations) && financial.obligations.length > 0;
    let envelope;
    if (action === 'release') envelope = expectedRelease;
    else if (action === 'refund') envelope = expectedRefund;
    else if (action === 'cancel') envelope = residual ? residualEnvelope : cancelEnvelope;
    else throw new Error(`fixture evaluator: unsupported action ${action}`);
    const out = JSON.parse(JSON.stringify(envelope));
    if (!out.effects || out.effects[0].id !== ordinary.Args.transferId) throw new Error(`fixture evaluator: transfer id mismatch for ${action}`);
    return out;
  }
  function createFakeAiken({ omit = null, qualify = false } = {}) {
    const seen = { check: 0, build: 0, generated: [] };
    const aikenRun = (args, cwd) => {
      if (args[0] === 'check') {
        seen.check += 1;
        const validator = fs.readFileSync(join(cwd, 'validators/financial_head.ak'), 'utf8');
        seen.generated = [...validator.matchAll(/^test ([A-Za-z0-9_]+)\(/gm)].map((match) => match[1]);
        const tests = seen.generated.filter((title) => title !== omit).map((title) => ({ title: qualify ? `financial_head.${title}` : title, status: 'success', kind: 'unit' }));
        return { status: 0, stdout: JSON.stringify({ summary: { fake: true }, modules: [{ name: 'financial_head', test: tests }] }), stderr: '' };
      }
      if (args[0] === 'build') { seen.build += 1; fs.writeFileSync(join(cwd, 'plutus.json'), `${JSON.stringify({ validators: [] })}\n`); return { status: 0, stdout: '', stderr: '' }; }
      throw new Error(`fixture aikenRun refuses args ${JSON.stringify(args)}`);
    };
    return { seen, aikenRun };
  }
  const dependencies = {
    'node:crypto': { createHash },
    'node:fs': { cpSync: fs.cpSync, existsSync: fs.existsSync, mkdirSync: fs.mkdirSync, readFileSync: fs.readFileSync, rmSync: fs.rmSync, symlinkSync: fs.symlinkSync, writeFileSync: fs.writeFileSync },
    'node:os': { tmpdir: () => '/fixture-tmp' },
    'node:path': { join },
    'node:assert': { deepStrictEqual: realmDeepStrictEqual },
    '../../moriarty-language/src/successor/financial-agreement-source-v5.ts': { createFinancialAgreementSourceV5: () => ({ evaluate }) },
    '../../moriarty-language/src/codec.ts': { canonicalEncode },
    './admit-custody.mjs': {
      admitCustody: ({ sourceText, seedText: seed, manifest }) => {
        if (!sourceText.includes('moriarty-financial-agreement-source/5')) return { ok: false, code: 'PROFILE_MISMATCH', detail: 'fixture admission profile', ledgerExecution: false, nativePins: false };
        const parsedSeed = JSON.parse(seed);
        if (parsedSeed.schemaVersion !== 'moriarty-financial-lifecycle-state/1') return { ok: false, code: 'SCHEMA', detail: 'fixture admission seed schema', ledgerExecution: false, nativePins: false };
        return { ok: true, hashes: JSON.parse(JSON.stringify(oracle.hashes || {})), manifest: JSON.parse(JSON.stringify(manifest)), instanceId: 'f01-fixture-instance', actions: ['release', 'refund', 'cancel'] };
      },
      fenceLifecycle: (financialPost) => ({ code: Array.isArray(financialPost && financialPost.obligations) && financialPost.obligations.length > 0 ? 'NONEMPTY_OBLIGATIONS' : 'OK' }),
    },
    './custody-oracle-bind.mjs': { bindOracleSpends: (results, _syntheticTime) => { if (!results || !Array.isArray(results.cases)) throw Object.assign(new Error('oracle results shape'), { code: 'ORACLE_DIVERGENCE' }); return { source: '', expectedTests: [], bound: [], skipped: [] }; } },
    './custody-capacity.mjs': { bindCapacity: ({ seed }) => (seed && seed.schemaVersion === 'moriarty-financial-lifecycle-state/1' ? { ok: true } : { ok: false, code: 'CAPACITY', detail: 'fixture seed schema', ledgerExecution: false, nativePins: false }) },
    './custody-time.mjs': {
      actionTimeGuards: () => { throw new Error('fixture world: actionTimeGuards not used on null syntheticTime path'); },
      isFixedUtxoProbe: () => false,
      isProductionProbeTime: (value) => value !== null && value !== undefined && value.productionArtifact === true,
      substituteTimeGuards: () => { throw new Error('fixture world: substituteTimeGuards not used on null syntheticTime path'); },
    },
    './lower-custody.mjs': {
      lowerCustody: () => ({ validator: 'validator financial_head {\n  spend(datum, redeemer, _input, _self) {\n    True\n  }\n}\ntest release_missing_lender_row() {\n  True\n}\ntest oracle_release_missing_lender_row() {\n  True\n}\n', expectedTests: F01_REQUIRED_TITLES.map((title) => ({ title, status: 'success' })) }),
      LowerError,
    },
    './compile-public.mjs': {
      parseAikenCheckJson: (stdout, _stderr) => { try { const json = JSON.parse(String(stdout || '')); const tests = []; for (const mod of json.modules || []) for (const item of mod.test || []) tests.push({ title: item.title, status: item.status, kind: item.kind, module: mod.name }); return { ok: true, tests, summary: json.summary || null, errors: [] }; } catch { return { ok: false, tests: [], summary: null, errors: ['AIKEN_JSON_MISSING'] }; } },
      ROOT: '/fixture-root',
      runAiken: () => { throw new Error('fixture world: default runAiken must be overridden by injected aikenRun'); },
    },
    './apply-head.mjs': {
      applyUnitParameters: ({ blueprintPath }) => { const blueprint = JSON.parse(fs.readFileSync(blueprintPath, 'utf8')); if (!Array.isArray(blueprint.validators) || blueprint.validators.length === 0) return { ok: false, code: 'AIKEN_CHECK', detail: 'blueprint titles', ledgerExecution: false, nativePins: false }; return { ok: false, code: 'AIKEN_CHECK', detail: 'blueprint titles', ledgerExecution: false, nativePins: false }; },
      CASH_VALIDATOR, STDLIB_TREE: '/fixture-stdlib', STDLIB_TREE_SHA256: STDLIB_SHA,
      stdlibTreeSha256: (treeRoot) => (treeRoot === '/fixture-stdlib' ? { ok: true, sha256: STDLIB_SHA, files: 65 } : { ok: false, code: 'STDLIB_PIN_MISMATCH' }),
    },
  };
  return Object.freeze({ dependencies, fs, createFakeAiken });
}
